  tdsrrc_IntraFreqMeasurementSysInfo_HCS_RSCP_LCR_r4   *intra_freq_meas_rscp_ptr = NULL;
  tdsrrc_IntraFreqMeasurementSysInfo_HCS_ECN0_LCR_r4   *intra_freq_meas_ecn0_ptr = NULL;

