  tdsrrc_NewIntraFreqCellSI_List_HCS_RSCP_LCR_r4       *rscp_intra_freq_cell_list_ptr = NULL;
  tdsrrc_NewIntraFreqCellSI_List_HCS_ECN0_LCR_r4       *ecn0_intra_freq_cell_list_ptr = NULL;

  uint8 i;
  uint16   cell_count = 0;
  uint32 idx=0,idy=0;
  uint32 cell_position = 0;
  tdsrrc_SysInfoType11_v590ext_IEs_newIntraFrequencyCellInfoList_v590ext * rel5_ext_ptr = NULL;
  tdsrrc_SysInfoType18 *sib18_ptr = NULL; /* Declared to store the value of SIB 18*/
  tdsrrc_PLMNsOfIntraFreqCellsList *tmp_rrc_PLMNsOfIntraFreqCellsList_ptr = NULL;
  rrc_plmn_identity_type tmp_plmn_identity;
  rrc_plmn_identity_type selected_plmn_identity;
  tdsrrc_int_cell_id_type  tmp_cell_id;
