#ifdef FEATURE_TDSCDMA_REL9
/*===========================================================================

FUNCTION   tdsrrcmeas_check_all_statusFlag_deact_in_DMO_config

DESCRIPTION 
  This is a fault-tolerance protection function when R9 MCM received by UE and
  DMO feature is disabled.
  Return TRUE if all statusFlag in DMO config are deactivate. False otherwise.
   
DEPENDENCIES
  None

RETURN VALUE
  Boolean

SIDE EFFECTS
  None

===========================================================================*/

boolean tdsrrcmeas_check_all_statusFlag_deact_in_DMO_config
(
  tdsrrc_CellDCHMeasOccasionInfo_TDD128_r9* dmo_ptr
)
{
  boolean all_deactivate = TRUE;
  uint8 i = 0;

  while (all_deactivate && (i < dmo_ptr->cellDCHMeasOccasionSequenceList.n)) 
  {
     if (dmo_ptr->cellDCHMeasOccasionSequenceList.elem[i].statusFlag == 
         tdsrrc_CellDCHMeasOccasionPattern_LCR_statusFlag_activate) 
     {
        all_deactivate = FALSE;
        break;
     }
     i++;
  }

  return all_deactivate;
}
#endif

/*===========================================================================

FUNCTION   tdsrrcmeas_process_pseudo_lte_list_update_ind

DESCRIPTION 
  This function process NAS TDSRRC_PSEUDO_LTE_LIST_UPDATE_IND

DEPENDENCIES
  None

RETURN VALUE
  None

SIDE EFFECTS
  None

===========================================================================*/
void tdsrrcmeas_process_pseudo_lte_list_update_ind
(
  tdsrrc_cmd_type *cmd_ptr
)
{
   if (!cmd_ptr)
   {
      TDSRRC_MSG0(MSG_LEGACY_ERROR, "tdsrrcmeas_process_pseudo_lte_list_update_ind got null cmd_ptr");
      return;
   }

   TDSRRC_MSG2(MSG_LEGACY_HIGH,"tdsrrcmeas_pseudo_lte_avail_enabled updated %d ==> %d",
               tdsrrcmeas_pseudo_lte_avail_enabled,
               cmd_ptr->cmd.rrc_pseudo_lte_avail_update_ind.can_use_pseudo);
   
   tdsrrcmeas_pseudo_lte_avail_enabled = cmd_ptr->cmd.rrc_pseudo_lte_avail_update_ind.can_use_pseudo;

#ifdef FEATURE_TDSCDMA_ABSOLUTE_PRIORITY
   if ((tdsrrcmcm_get_rrc_mode() == TDSRRC_MODE_ACTIVE)
       && (tdsrrc_get_state() != TDSRRC_STATE_CELL_DCH)
       && (tdsrrc_get_state() != TDSRRC_STATE_CONNECTING)
      )
   {
      TDSRRC_MSG0(MSG_LEGACY_HIGH, "tdsrrcmeas_process_pseudo_lte_list_update_ind: update pseudo SIB19");

      /* Free pseudo SIB19 to allow update to the same cell */
      tdsrrcsibdb_free_pseudo_sib19();
      
      if ((tdsrrccsp_get_curr_scan() == RRC_CSP_TD2TD_BPLMN_MANUAL_SCAN)
          || (tdsrrccsp_get_curr_scan() == RRC_CSP_TD2TD_BPLMN_AUTOMATIC_SCAN)
          || (tdsrrccsp_get_curr_scan() == RRC_CSP_TD2G_BPLMN_AUTOMATIC_SCAN)
          || (tdsrrccsp_get_curr_scan() == RRC_CSP_TD2G_BPLMN_MANUAL_SCAN))
      {
         /* Delay sending meas_req of EUTRA after LTE available DB changes when BPLMN ongoing (leverage CR663848)
          */
         TDSRRC_MSG0(MSG_LEGACY_HIGH,"Delay sending meas_req of EUTRA after pseudo LTE avail change when BPLMN ongoing (leverage CR663848)");
         tdsrrc_update_eutra_priority_info_meas_need = TRUE;
      }
      else
         tdsrrcmeas_configure_l1_with_priority_info_eutra_cell_list();
   }
#else
   TDSRRC_MSG0(MSG_LEGACY_HIGH, "tdsrrcmeas_process_pseudo_lte_list_update_ind: FEATURE_TDSCDMA_ABSOLUTE_PRIORITY not defined. Do nothing");
#endif
}


